__NUXT_JSONP__("/desarrollo-sostenible/eventos/sembrando_vida_es_un_programa_que_podria_mejorarse_en_la_siguiente_administracion_federal_laure_delalande", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"sembrando_vida_es_un_programa_que_podria_mejorarse_en_la_siguiente_administracion_federal_laure_delalande",title:"Sembrando Vida es un programa que podría mejorarse  en la siguiente administración federal: Laure Delalande",date:"2023-09-27T23:34:30.652Z",img:"https:\u002F\u002Fucarecdn.com\u002Fbc057773-db6f-4609-baed-57ea6a928e82\u002F","img-alt":"Laure Delalande, Sembrando vida",autor:"Ethos",category:"desarrollo-sostenible",extracto:"Al participar en la presentación del informe «Sembrando Vida y la reducción de la violencia», de Noria Research Mexico & Central America, Laure Delalande destacó el potencial del programa federal para reducir la pobreza y promover la reforestación.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"Sembrando Vida, el principal programa del gobierno federal dirigido al campo, tiene un buen diseño; sin embargo, tiene varios aspectos en su implementación que pueden mejorarse, y corresponderá a la siguiente administración hacerlo, expresó Laure Delalande, directora de Inclusión y Desarrollo Sostenible en Ethos, en la presentación del informe «Sembrando Vida y la reducción de la violencia», de "},{type:b,tag:d,props:{href:"https:\u002F\u002Fnoria-research.com\u002Fmxac\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Noria Research Mexico & Central America"}]},{type:a,value:"."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Destacó que el programa tiene elementos interesantes, pero sus principales errores se relacionan con la planeación, ya que fue lanzado al vapor. En ese sentido, es fundamental poner orden y lograr que cumpla con los dos objetivos principales: reducción de la pobreza, desarrollo rural,  y de manera más secundaria, la reforestación en materia ambiental."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"Respecto a su incidencia en la disminución de la violencia, destacó que no fue creado para ello, pues su fin no es promover la sustitución de cultivos ilícitos. “Si estuviéramos pensando en una política de sustitución de cultivos ilícitos, lo que se tendría que plantear es una compensación monetaria a la altura de los ingresos que genera el cultivo ilícito, o bien una alternativa agronómica que realmente sea competitiva con estos”, expresó."}]},{type:a,value:i},{type:b,tag:c,props:{},children:[{type:a,value:"El informe fue presentado por Paul Freezer, de Noria Research MXCA, y lo comentaron también Carolina Torreblanca, de Data Cívica"},{type:b,tag:d,props:{href:j,rel:[e,f,g],target:h},children:[{type:a,value:j}]},{type:a,value:" y Víctor López Illescas, de "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.fordfoundation.org\u002F",rel:[e,f,g],target:h},children:[{type:a,value:"Ford Foundation"}]},{type:a,value:", Moderó Teresa Martínez Trujillo, de Noria Research MXCA."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fsembrando_vida_es_un_programa_que_podria_mejorarse_en_la_siguiente_administracion_federal_laure_delalande",extension:".md",createdAt:k,updatedAt:k}}],fetch:{},mutations:[]}}("text","element","p","a","nofollow","noopener","noreferrer","_blank","\n","https:\u002F\u002Fdatacivica.org\u002F","2023-10-09T22:42:25.551Z")));